insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_reflection','reflection','noun','careful thought about something, especially to understand or judge it','[{"senseId":"reflection_1","meaning":"careful thought about something, especially to understand or judge it","acceptedParaphrases":["careful thought","serious consideration"],"masteryContexts":[{"contextId":"u3_41_reflection_meaning","text":"After the cooking project, each student wrote a short reflection on what had gone well and what could improve.","meaning":"careful thought about past events or work","wrongMeanings":["a list of future plans for a project","a report written by a teacher alone","a prize given for good work"]},{"contextId":"u3_41_reflection_paraphrase","text":"The owner read the customer comments and, after some reflection, decided to simplify the menu.","meaning":"time spent thinking carefully","wrongMeanings":["time spent eating a quick lunch","time spent waiting for guests to arrive","time spent cleaning the kitchen after work"]}],"situationDistractors":["The student ordered a sandwich without reading the menu and ate it in a hurry.","The chef answered at once, started cooking and never stopped to think.","The class tasted five dishes and shouted their votes at the same moment.","The market stall sells local vegetables at low prices.","The cafe closes early on Sundays.","The chef learned the recipe from his grandmother."],"gapDistractors":[{"contextId":"u3_41_reflection_gap_1","answer":"reflection","wrong":["travel","laughter","payment"]},{"contextId":"u3_41_reflection_gap_2","answer":"reflection","wrong":["complaint","recipe","picture"]},{"contextId":"u3_41_reflection_gap_3","answer":"reflection","wrong":["complaint","receipt","schedule"]}],"spellingErrors":["refelction","reflaction","reflecsion","reflektion","reflecton","relfection"],"wordFamilyForms":[{"form":"reflection","partOfSpeech":"noun","example":"The chef spent a quiet hour in reflection before she decided on the new menu.","pedagogicallyUseful":true},{"form":"reflect","partOfSpeech":"verb","example":"Take a few minutes to reflect on what you have learned from the cooking class.","pedagogicallyUseful":true,"altExample":"Good cooks reflect on their mistakes and then try the recipe again."},{"form":"reflective","partOfSpeech":"adjective","example":"Ravi is a quiet, reflective student who thinks carefully before he answers.","pedagogicallyUseful":true,"altExample":"She kept a reflective diary of her work in the school kitchen."}],"masteryPassages":[{"passageId":"u3_41_reflection_passage_1","contextId":"u3_41_reflection_gap_1","text":"At the end of the term, the teacher asked the class to look back at their cooking project. Each student wrote a short ____ on what had gone well and what they would change next time.","answer":"reflection"},{"passageId":"u3_41_reflection_passage_2","contextId":"u3_41_reflection_gap_2","text":"The restaurant owner read all the customer comments carefully. After a long period of quiet ____, she decided to remove three dishes from the menu.","answer":"reflection"}],"contextDependentParaphrases":[],"wrongParaphrases":["quick decision","strong feeling","simple rule"],"misleadingDistractors":["a quick guess made without thinking","a sudden feeling of hunger","a formal rule about behaviour"]}]'::jsonb,'["reflect","reflective"]'::jsonb,'["on reflection","quiet reflection","written reflection"]'::jsonb,'live'),
('vocab_organiser','organiser','noun','a person who plans and arranges an event or activity','[{"senseId":"organiser_1","meaning":"a person who plans and arranges an event or activity","acceptedParaphrases":["event planner","person who arranges events"],"masteryContexts":[{"contextId":"u3_42_organiser_meaning","text":"The organiser of the school food festival booked forty stalls and invited every family in the town.","meaning":"the person who plans and arranges an event","wrongMeanings":["the person who pays for an event and its food","the person who takes part in an event as a guest","the person who writes about an event afterwards"]},{"contextId":"u3_42_organiser_paraphrase","text":"The organiser asked every cook to arrive by eight o’clock so that the market could open on time.","meaning":"the person in charge of planning an activity","wrongMeanings":["the person who judges the best cook in a contest","the person who sells tickets to visitors at the door","the person who films the activity for the school"]}],"situationDistractors":["A visitor tasted the soup at one stall and left without buying anything.","A cook washed the pans when the event had finished.","The audience clapped when the singer finished the last song.","The cafe opens at eight and closes at six.","The chef wore a white hat and an apron.","There were four tables near the window."],"gapDistractors":[{"contextId":"u3_42_organiser_gap_1","answer":"organiser","wrong":["visitor","winner","neighbour"]},{"contextId":"u3_42_organiser_gap_2","answer":"organiser","wrong":["winner","visitor","customer"]},{"contextId":"u3_42_organiser_gap_3","answer":"organiser","wrong":["winner","customer","neighbour"]}],"spellingErrors":["organizer","orginiser","orgainser","organisor","organisier","organnaiser"],"wordFamilyForms":[{"form":"organiser","partOfSpeech":"noun","example":"The organiser of the picnic asked each family to bring one dish.","pedagogicallyUseful":true},{"form":"organise","partOfSpeech":"verb","example":"Our class will organise a bake sale to raise money for the school trip.","pedagogicallyUseful":true,"altExample":"The students organise the tables before the guests arrive."},{"form":"organisation","partOfSpeech":"noun","example":"Good organisation helped the team serve three hundred guests in one hour.","pedagogicallyUseful":true,"altExample":"The success of the festival depended on careful organisation."}],"masteryPassages":[{"passageId":"u3_42_organiser_passage_1","contextId":"u3_42_organiser_gap_1","text":"The school wanted to hold a food festival for all families. The ____ spent three months booking stalls, choosing a date and sending invitations.","answer":"organiser"},{"passageId":"u3_42_organiser_passage_2","contextId":"u3_42_organiser_gap_2","text":"Everyone enjoyed the picnic because nothing went wrong. The ____ had made a list of who would bring each dish and had checked the weather forecast.","answer":"organiser"}],"contextDependentParaphrases":[],"wrongParaphrases":["guest speaker","head waiter","food critic"],"misleadingDistractors":["a person who takes part in an activity","a person who pays for an event","a person who cleans after an event"]}]'::jsonb,'["organise","organisation"]'::jsonb,'["event organiser","festival organiser","chief organiser"]'::jsonb,'live'),
('vocab_presenter','presenter','noun','a person who introduces a programme or gives a talk to an audience','[{"senseId":"presenter_1","meaning":"a person who introduces a programme or gives a talk to an audience","acceptedParaphrases":["host","person who introduces a programme"],"masteryContexts":[{"contextId":"u3_43_presenter_meaning","text":"The presenter of the radio programme introduced the guest chef and asked her about her favourite recipes.","meaning":"a person who introduces and leads a programme","wrongMeanings":["a person who cooks the food for a programme","a person who watches a programme at home","a person who pays for a programme to be made"]},{"contextId":"u3_43_presenter_paraphrase","text":"At the school conference, each presenter had ten minutes to explain a project on healthy eating.","meaning":"a person who gives a talk to an audience","wrongMeanings":["a person who asks the audience hard questions","a person who sits in the audience and listens","a person who sells tickets for the talk"]}],"situationDistractors":["The audience sat quietly and ate their sandwiches before the show began.","The camera operator set up the lights and checked the sound.","The viewers switched off the television and went to bed.","The waiter wiped the table and brought the menus.","The queue outside the cafe moved quickly.","She ordered tea and a slice of lemon cake."],"gapDistractors":[{"contextId":"u3_43_presenter_gap_1","answer":"presenter","wrong":["driver","farmer","neighbour"]},{"contextId":"u3_43_presenter_gap_2","answer":"presenter","wrong":["waiter","driver","farmer"]},{"contextId":"u3_43_presenter_gap_3","answer":"presenter","wrong":["farmer","neighbour","tourist"]}],"spellingErrors":["presentor","presanter","pressenter","presentar","prezenter","presnter"],"wordFamilyForms":[{"form":"presenter","partOfSpeech":"noun","example":"The presenter of the cooking programme welcomed the viewers.","pedagogicallyUseful":true},{"form":"present","partOfSpeech":"verb","example":"Each group must present its findings about school lunches to the class.","pedagogicallyUseful":true,"altExample":"Students will present a short talk about local food to the whole school."},{"form":"presentation","partOfSpeech":"noun","example":"Her presentation about vegetarian food included photographs and a short quiz.","pedagogicallyUseful":true,"altExample":"The class gave a presentation on how bread is made."}],"masteryPassages":[{"passageId":"u3_43_presenter_passage_1","contextId":"u3_43_presenter_gap_1","text":"Millions of people watch the Saturday cooking show. The ____ welcomes the viewers, introduces the guest chef and explains each recipe in simple words.","answer":"presenter"},{"passageId":"u3_43_presenter_passage_2","contextId":"u3_43_presenter_gap_2","text":"At the school science fair, each student stood in front of a small crowd. The first ____ explained how salt keeps food fresh, and the others took notes.","answer":"presenter"}],"contextDependentParaphrases":[],"wrongParaphrases":["guest","viewer","cook"],"misleadingDistractors":["a person who cooks the food for a programme","a person who watches a programme at home","a person who pays for a programme"]}]'::jsonb,'["present","presentation"]'::jsonb,'["television presenter","radio presenter","news presenter"]'::jsonb,'live'),
('vocab_evaluate','evaluate','verb','to judge how good, useful or successful something is by thinking about it carefully','[{"senseId":"evaluate_1","meaning":"to judge how good, useful or successful something is by thinking about it carefully","acceptedParaphrases":["assess","judge the quality of"],"masteryContexts":[{"contextId":"u3_44_evaluate_meaning","text":"Before choosing a restaurant, we read reviews to evaluate the quality of its food and service.","meaning":"judge how good something is","wrongMeanings":["decide how much to pay for it","notice what is missing from it","describe what it looks like"]},{"contextId":"u3_44_evaluate_paraphrase","text":"Students were asked to evaluate three school lunch menus and decide which one offered the best value.","meaning":"judge the quality or value of something carefully","wrongMeanings":["choose something quickly without thinking","copy something exactly as it was shown","make something better by changing it"]}],"situationDistractors":["The cook added salt to the soup and stirred it without tasting it.","The waiter wrote down the order and walked to the kitchen.","The class ate their lunch and put the plates in the sink.","The restaurant has red tablecloths and candles.","The bill was paid by credit card.","The market opens at six every morning."],"gapDistractors":[{"contextId":"u3_44_evaluate_gap_1","answer":"evaluate","wrong":["peel","pour","wrap"]},{"contextId":"u3_44_evaluate_gap_2","answer":"evaluate","wrong":["copy","fold","sell"]},{"contextId":"u3_44_evaluate_gap_3","answer":"evaluate","wrong":["carry","fold","repair"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u3_44_evaluate_passage_1","contextId":"u3_44_evaluate_gap_1","text":"The magazine sent a team of critics to the new restaurant. They had to ____ the food, the service and the prices, and then give the restaurant a score out of ten.","answer":"evaluate"},{"passageId":"u3_44_evaluate_passage_2","contextId":"u3_44_evaluate_gap_2","text":"Before the school changed its lunch menu, the cooks asked the students to try the new dishes. The teachers will then ____ the results and decide which meals to keep.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["prepare","repeat","delay"],"misleadingDistractors":["to prepare food for a large group","to repeat a recipe from memory","to choose a table in a restaurant"],"grammarForms":{"base":"evaluate","thirdPerson":"evaluates","past":"evaluated","pastParticiple":"evaluated","ing":"evaluating"}}]'::jsonb,'[]'::jsonb,'["carefully evaluate","evaluate the quality","critically evaluate"]'::jsonb,'live'),
('vocab_consume','consume','verb','to eat or drink something, or to use up an amount of something','[{"senseId":"consume_1","meaning":"to eat or drink something, or to use up an amount of something","acceptedParaphrases":["eat or drink","use up"],"masteryContexts":[{"contextId":"u3_45_consume_meaning","text":"A family of four can consume a large bag of rice in less than two weeks.","meaning":"eat or use up an amount of food","wrongMeanings":["buy or store a large amount of food","cook or serve a large amount of food","waste or throw away a large amount of food"]},{"contextId":"u3_45_consume_paraphrase","text":"Most adults consume at least one cup of tea or coffee every day.","meaning":"drink or eat something regularly","wrongMeanings":["buy or order something regularly","make or prepare something regularly","avoid or refuse something regularly"]}],"situationDistractors":["The farmer grew rice in a flooded field and sold it at the market.","The shop assistant put the rice on the shelf and counted the bags.","The chef bought vegetables and carried them to the kitchen.","The restaurant has a garden at the back.","The tickets were printed on blue paper.","The waiter carried the plates on a large tray."],"gapDistractors":[{"contextId":"u3_45_consume_gap_1","answer":"consume","wrong":["grow","repair","carry"]},{"contextId":"u3_45_consume_gap_2","answer":"consume","wrong":["repair","forget","answer"]},{"contextId":"u3_45_consume_gap_3","answer":"consume","wrong":["paint","repair","forget"]}],"spellingErrors":["consum","comsume","consoume","cunsume","consuem","consumme"],"wordFamilyForms":[{"form":"consume","partOfSpeech":"verb","example":"Families in cold regions consume more hot soup in winter than in summer.","pedagogicallyUseful":true},{"form":"consumer","partOfSpeech":"noun","example":"Every consumer has the right to clear information on food labels.","pedagogicallyUseful":true,"altExample":"The shop gives each consumer a free recipe card."},{"form":"consumption","partOfSpeech":"noun","example":"The daily consumption of water in the school kitchen is about two hundred litres.","pedagogicallyUseful":true,"altExample":"Rice consumption has risen steadily in the city."}],"masteryPassages":[{"passageId":"u3_45_consume_passage_1","contextId":"u3_45_consume_gap_1","text":"The school canteen serves about six hundred students each day. Together, the students ____ nearly two hundred loaves of bread every week.","answer":"consume"},{"passageId":"u3_45_consume_passage_2","contextId":"u3_45_consume_gap_2","text":"A busy restaurant needs a lot of supplies. In one weekend, the kitchen can ____ fifty kilograms of potatoes and thirty litres of oil.","answer":"consume"}],"contextDependentParaphrases":[],"wrongParaphrases":["cook or serve","buy or sell","grow or pick"],"misleadingDistractors":["to prepare and cook something carefully","to buy something from a shop","to throw something away after use"],"grammarForms":{"base":"consume","thirdPerson":"consumes","past":"consumed","pastParticiple":"consumed","ing":"consuming"}}]'::jsonb,'["consumer","consumption"]'::jsonb,'["consume food","consume large amounts","regularly consume"]'::jsonb,'live'),
('vocab_balanced','balanced','adjective','having the right amounts of different things, so that no one part is too big','[{"senseId":"balanced_1","meaning":"having the right amounts of different things, so that no one part is too big","acceptedParaphrases":["well-proportioned","in the right proportions"],"masteryContexts":[{"contextId":"u3_46_balanced_meaning","text":"The school lunch is balanced, with vegetables, protein, rice and a piece of fruit.","meaning":"including the right amounts of different foods","wrongMeanings":["containing only foods that are cheap to buy","including only foods that are grown nearby","containing foods that are served very hot"]},{"contextId":"u3_46_balanced_paraphrase","text":"The chef planned a balanced menu, with light dishes placed between the rich ones.","meaning":"arranged so that no part is too heavy or too large","wrongMeanings":["arranged in order from the cheapest to the dearest","arranged so that every dish is served at the same time","arranged so that each dish comes from a different country"]}],"situationDistractors":["The lunch box held ten chocolate bars and nothing else.","The cook served a huge bowl of plain rice with no other food.","The plate was almost empty, with only one small pea in the middle.","The cafe opens at eight and closes at six.","The queue outside the cafe moved quickly.","The waiter wiped the table and brought the menus."],"gapDistractors":[{"contextId":"u3_46_balanced_gap_1","answer":"balanced","wrong":["crowded","famous","cheap"]},{"contextId":"u3_46_balanced_gap_2","answer":"balanced","wrong":["crowded","famous","noisy"]},{"contextId":"u3_46_balanced_gap_3","answer":"balanced","wrong":["crowded","famous","noisy"]}],"spellingErrors":["ballanced","balansed","balenced","balancd","balanceed","balaned"],"wordFamilyForms":[{"form":"balanced","partOfSpeech":"adjective","example":"The school lunch is balanced, with vegetables, protein and rice.","pedagogicallyUseful":true},{"form":"balance","partOfSpeech":"verb","example":"Good cooks balance sweet and sour flavours in the same dish.","pedagogicallyUseful":true},{"form":"unbalanced","partOfSpeech":"adjective","example":"A lunch of only chips and sweets is unbalanced, because it has no variety.","pedagogicallyUseful":true},{"form":"imbalance","partOfSpeech":"noun","example":"There is an imbalance on the menu, because nearly every dish contains meat.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u3_46_balanced_passage_1","contextId":"u3_46_balanced_gap_1","text":"The school canteen follows new guidelines. Every lunch must be ____, with some vegetables, some protein and some rice or bread.","answer":"balanced"},{"passageId":"u3_46_balanced_passage_2","contextId":"u3_46_balanced_gap_2","text":"The chef did not want the guests to feel too full by the third course. She planned a ____ menu, putting light dishes between the rich ones.","answer":"balanced"}],"contextDependentParaphrases":[],"wrongParaphrases":["over-salted","half-cooked","ill-prepared"],"misleadingDistractors":["containing only one kind of food","served in very small amounts","prepared with a lot of oil"]}]'::jsonb,'["balance","unbalanced","imbalance"]'::jsonb,'["balanced diet","balanced meal","well balanced"]'::jsonb,'live'),
('vocab_calorie','calorie','noun','a unit used to measure the energy that food provides','[{"senseId":"calorie_1","meaning":"a unit used to measure the energy that food provides","acceptedParaphrases":["unit of food energy","measure of food energy"],"masteryContexts":[{"contextId":"u3_47_calorie_meaning","text":"A calorie is a unit that shows how much energy a food provides.","meaning":"a unit for measuring the energy in food","wrongMeanings":["a unit for measuring the weight of food","a unit for measuring the heat of an oven","a unit for measuring the time needed to cook"]},{"contextId":"u3_47_calorie_paraphrase","text":"The menu shows the calorie value of every dish next to its price.","meaning":"a measure of the energy in food","wrongMeanings":["a measure of the salt in food","a measure of the cost of food","a measure of the age of food"]}],"situationDistractors":["The cook weighed the flour and added two spoons of sugar.","The oven was heated to two hundred degrees before the bread went in.","The label listed the country where the rice was grown.","The chef wore a white hat and an apron.","There were four tables near the window.","The restaurant opens on Mondays."],"gapDistractors":[{"contextId":"u3_47_calorie_gap_1","answer":"calorie","wrong":["gram","litre","degree"]},{"contextId":"u3_47_calorie_gap_2","answer":"calorie","wrong":["page","word","seat"]},{"contextId":"u3_47_calorie_gap_3","answer":"calorie","wrong":["colour","shape","size"]}],"spellingErrors":["calory","calorey","callorie","calorrie","kalorie","calarie"],"masteryPassages":[{"passageId":"u3_47_calorie_passage_1","contextId":"u3_47_calorie_gap_1","text":"Food gives the body the energy it needs to move and think. Scientists measure this energy in units, and the unit that they use is the ____.","answer":"calorie"},{"passageId":"u3_47_calorie_passage_2","contextId":"u3_47_calorie_gap_2","text":"Many packets of food show information about their contents on the back. Next to the amount of salt and fat, you can find the ____ count for one portion.","answer":"calorie"}],"contextDependentParaphrases":[],"wrongParaphrases":["unit of food weight","type of cooking oil","part of a recipe"],"misleadingDistractors":["a unit used to measure the weight of food","a unit used to measure the heat of an oven","a unit used to measure the time needed to cook"]}]'::jsonb,'[]'::jsonb,'["calorie count","calorie content","low-calorie"]'::jsonb,'live'),
('vocab_hygienic','hygienic','adjective','clean in a way that stops dirt and germs from spreading','[{"senseId":"hygienic_1","meaning":"clean in a way that stops dirt and germs from spreading","acceptedParaphrases":["clean and germ-free","free from dirt and germs"],"masteryContexts":[{"contextId":"u3_48_hygienic_meaning","text":"The inspector praised the hygienic kitchen, where staff washed their hands and cleaned every surface.","meaning":"clean in a way that stops germs spreading","wrongMeanings":["tidy in a way that makes space for guests","neat in a way that pleases the eye","new in a way that attracts more customers"]},{"contextId":"u3_48_hygienic_paraphrase","text":"It is not hygienic to prepare raw chicken and salad on the same board.","meaning":"safe because it avoids spreading dirt and germs","wrongMeanings":["rude because it is not the usual custom","impossible because it takes too much time","expensive because it needs special tools"]}],"situationDistractors":["The cook left the raw meat on the table next to the bread for an hour.","The waiter dropped a spoon, wiped it on his shirt and put it back on the table.","The kitchen floor was covered in old food and the bins were overflowing.","The restaurant has red tablecloths and candles.","The bill was paid by credit card.","The cafe closes early on Sundays."],"gapDistractors":[{"contextId":"u3_48_hygienic_gap_1","answer":"hygienic","wrong":["crowded","famous","noisy"]},{"contextId":"u3_48_hygienic_gap_2","answer":"hygienic","wrong":["useful","cheap","famous"]},{"contextId":"u3_48_hygienic_gap_3","answer":"hygienic","wrong":["noisy","famous","heavy"]}],"spellingErrors":["hygenic","hyginic","higienic","hygeinic","hygienick","hygienik"],"wordFamilyForms":[{"form":"hygienic","partOfSpeech":"adjective","example":"The health inspector found that the kitchen was hygienic.","pedagogicallyUseful":true},{"form":"hygiene","partOfSpeech":"noun","example":"Good hygiene in the kitchen starts with washing your hands.","pedagogicallyUseful":true,"altExample":"Teachers explain food hygiene to students before they use the kitchen."},{"form":"hygienically","partOfSpeech":"adverb","example":"All the food is prepared hygienically in a separate room.","pedagogicallyUseful":true,"altExample":"The knives must be stored hygienically after every lesson."}],"masteryPassages":[{"passageId":"u3_48_hygienic_passage_1","contextId":"u3_48_hygienic_gap_1","text":"Health inspectors visit restaurants without warning. They check that the kitchen is ____, with shining surfaces, fresh water and staff who wash their hands.","answer":"hygienic"},{"passageId":"u3_48_hygienic_passage_2","contextId":"u3_48_hygienic_gap_2","text":"Raw meat can carry germs that spread to other food. For this reason, it is not ____ to use the same knife for chicken and for salad.","answer":"hygienic"}],"contextDependentParaphrases":[],"wrongParaphrases":["cheap and long-lasting","warm and well-cooked","fresh and full of flavour"],"misleadingDistractors":["tidy and well organised","cold and kept fresh","old and rarely used"]}]'::jsonb,'["hygiene","hygienically"]'::jsonb,'["hygienic conditions","hygienic kitchen","perfectly hygienic"]'::jsonb,'live'),
('vocab_appetising','appetising','adjective','looking or smelling so good that you want to eat it','[{"senseId":"appetising_1","meaning":"looking or smelling so good that you want to eat it","acceptedParaphrases":["mouth-watering","tempting"],"masteryContexts":[{"contextId":"u3_49_appetising_meaning","text":"The pizza arrived hot from the oven, with melted cheese and a delicious smell, and it looked very appetising.","meaning":"looking so good that you want to eat it","wrongMeanings":["looking so unusual that you are surprised by it","looking so expensive that you cannot buy it","looking so new that nobody has tried it"]},{"contextId":"u3_49_appetising_paraphrase","text":"Chefs arrange food carefully on the plate to make it look more appetising.","meaning":"attractive and making people want to eat","wrongMeanings":["noisy and making people want to leave","cheap and making people want to return","colourful and making people want to take photographs"]}],"situationDistractors":["The soup was cold, grey and full of lumps, so nobody wanted to try it.","The meal was served on time, but the portions were small.","The cook carried the heavy pot from the stove to the table.","The tickets were printed on blue paper.","The restaurant has a garden at the back.","The chef learned the recipe from his grandmother."],"gapDistractors":[{"contextId":"u3_49_appetising_gap_1","answer":"appetising","wrong":["crowded","noisy","heavy"]},{"contextId":"u3_49_appetising_gap_2","answer":"appetising","wrong":["crowded","noisy","heavy"]},{"contextId":"u3_49_appetising_gap_3","answer":"appetising","wrong":["crowded","noisy","famous"]}],"spellingErrors":["appetizing","apetising","appetsing","appetiseing","appitising","appettising"],"wordFamilyForms":[{"form":"appetising","partOfSpeech":"adjective","example":"The smell of fresh bread from the bakery was very appetising.","pedagogicallyUseful":true},{"form":"appetite","partOfSpeech":"noun","example":"The long walk along the beach gave us a good appetite for lunch.","pedagogicallyUseful":true,"altExample":"After the long hike, the whole group had a big appetite."},{"form":"unappetising","partOfSpeech":"adjective","example":"The grey, lumpy porridge looked unappetising, so few students ate it.","pedagogicallyUseful":true,"altExample":"The cold, grey soup looked so unappetising that nobody finished it."}],"masteryPassages":[{"passageId":"u3_49_appetising_passage_1","contextId":"u3_49_appetising_gap_1","text":"The bakery opens at five o’clock every morning. The smell of fresh bread is so ____ that people queue outside before the door opens.","answer":"appetising"},{"passageId":"u3_49_appetising_passage_2","contextId":"u3_49_appetising_gap_2","text":"The soup tasted wonderful, but it was grey and lumpy. Because it did not look ____, many guests refused to try it.","answer":"appetising"}],"contextDependentParaphrases":[],"wrongParaphrases":["eye-catching","long-lasting","well-known"],"misleadingDistractors":["tasting too strongly of salt","served hot and ready to eat","cheap enough for everyone to buy"]}]'::jsonb,'["appetite","unappetising"]'::jsonb,'["look appetising","appetising smell","appetising meal"]'::jsonb,'live'),
('vocab_cuisine','cuisine','noun','a style of cooking that is typical of a particular place or culture','[{"senseId":"cuisine_1","meaning":"a style of cooking that is typical of a particular place or culture","acceptedParaphrases":["style of cooking","cooking tradition"],"masteryContexts":[{"contextId":"u3_50_cuisine_meaning","text":"Many tourists travel to Italy to enjoy the local cuisine, especially fresh pasta and pizza.","meaning":"the style of cooking of a particular place","wrongMeanings":["the type of farming found in a particular place","the kind of weather found in a particular place","the price of food in a particular place"]},{"contextId":"u3_50_cuisine_paraphrase","text":"The restaurant serves Korean cuisine, so the menu includes rice dishes, soups and spicy vegetables.","meaning":"cooking that is typical of a country or culture","wrongMeanings":["kitchen tools that are typical of a country or culture","shops that are popular in a country or culture","farming that is typical of a country or culture"]}],"situationDistractors":["The farmer sold fresh tomatoes at the market on Saturday morning.","The waiter brought the bill and a mint to every table.","The chef tasted the soup, added salt and stirred it again.","The queue outside the cafe moved quickly.","The restaurant opens on Mondays.","The bill was paid by credit card."],"gapDistractors":[{"contextId":"u3_50_cuisine_gap_1","answer":"cuisine","wrong":["weather","music","language"]},{"contextId":"u3_50_cuisine_gap_2","answer":"cuisine","wrong":["weather","music","transport"]},{"contextId":"u3_50_cuisine_gap_3","answer":"cuisine","wrong":["clothing","music","transport"]}],"spellingErrors":["cuisene","quisine","cuisin","cusine","cuisinne","cuizine"],"masteryPassages":[{"passageId":"u3_50_cuisine_passage_1","contextId":"u3_50_cuisine_gap_1","text":"My cousin loves trying food from other countries. Last summer he travelled to Japan, where he discovered a ____ based on rice, fish and fresh vegetables.","answer":"cuisine"},{"passageId":"u3_50_cuisine_passage_2","contextId":"u3_50_cuisine_gap_2","text":"The school held an international evening. Each class chose a country and served dishes that were typical of its ____, from Mexican tacos to Indian curry.","answer":"cuisine"}],"contextDependentParaphrases":[],"wrongParaphrases":["place for eating","list of dishes","way of storing food"],"misleadingDistractors":["a place where food is sold","a list of dishes in a restaurant","a method used to keep food fresh"]}]'::jsonb,'[]'::jsonb,'["local cuisine","regional cuisine","traditional cuisine"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
values
